  ('Adrian Vale', 'Business Growth Partner', 'I Help Businesses', array['Grow Online', 'Win More Clients', 'Rank on Google', 'Sell Online']::text[], 'Websites, branding and digital marketing for small businesses and startups. One partner from strategy to launch, focused on real results.', 'I''m Adrian Vale, a web developer and digital strategist. For 8 years I have helped local shops, agencies and startups turn their ideas into websites that bring customers.', 'hello@adrianvale.demo', '+44 20 7946 0000', 'London, United Kingdom', '/demo/avatar-owner.svg', '/demo/hero-portrait.svg', null, null, 'Available for new projects', '120+ businesses trust my work', 'Strategy, Design & Code — All in One Place', '/demo/about-portrait.svg', array['Idea Validation', 'Business Strategy', 'Online Business', 'Market Research']::text[], 8, '["/demo/work-meeting.svg","/demo/work-desk.svg","/demo/work-team.svg"]'::jsonb, '[{"platform":"facebook","url":"https://facebook.com/"},{"platform":"linkedin","url":"https://linkedin.com/"},{"platform":"instagram","url":"https://instagram.com/"},{"platform":"x","url":"https://x.com/"}]'::jsonb, '[{"name":"Next.js","icon":"nextjs"},{"name":"Figma","icon":"figma"},{"name":"WordPress","icon":"wordpress"}]'::jsonb);
