insert into public.projects (title, slug, category, year, client, role, intro, challenge, solution, result, cover_image_url, gallery, live_url, likes, featured, status, sort_order) values
  ('LearnHub Online Academy', 'learnhub-online-academy', 'Websites', 2026, 'LearnHub', 'Strategy, Design & Development', 'A course website and student portal for an online academy with 5,000+ learners.', 'The business was getting traffic but very few enquiries. The old website was slow on mobile, hard to update and did not explain clearly why customers should choose them.', 'We started with a short discovery workshop, rewrote the key messages, and designed a fast, mobile-first website with clear calls to action. A simple dashboard lets the team update content without a developer.', 'Page speed improved to 95+, and enquiries more than doubled in the first three months. The team now publishes new offers and articles every week on their own.', '/demo/project-learnhub.svg', '["/demo/project-learnhub.svg","/demo/project-ledgerly.svg"]'::jsonb, 'https://example.com', 320, true, 'published', 1),
  ('Aurora Boutique Store', 'aurora-boutique-store', 'E-commerce', 2026, 'Aurora Boutique', 'E-commerce Design & Build', 'A fashion storefront with quick checkout, wishlists and a monthly lookbook.', 'The business was getting traffic but very few enquiries. The old website was slow on mobile, hard to update and did not explain clearly why customers should choose them.', 'We started with a short discovery workshop, rewrote the key messages, and designed a fast, mobile-first website with clear calls to action. A simple dashboard lets the team update content without a developer.', 'Page speed improved to 95+, and enquiries more than doubled in the first three months. The team now publishes new offers and articles every week on their own.', '/demo/project-aurora.svg', '["/demo/project-aurora.svg","/demo/project-brewly.svg"]'::jsonb, 'https://example.com', 410, true, 'published', 2),
  ('Ledgerly Finance Dashboard', 'ledgerly-finance-dashboard', 'Web Apps', 2025, 'Ledgerly', 'UI/UX Design, Front-end', 'An invoicing and cash-flow dashboard for freelancers and small teams.', 'The business was getting traffic but very few enquiries. The old website was slow on mobile, hard to update and did not explain clearly why customers should choose them.', 'We started with a short discovery workshop, rewrote the key messages, and designed a fast, mobile-first website with clear calls to action. A simple dashboard lets the team update content without a developer.', 'Page speed improved to 95+, and enquiries more than doubled in the first three months. The team now publishes new offers and articles every week on their own.', '/demo/project-ledgerly.svg', '["/demo/project-ledgerly.svg","/demo/project-learnhub.svg"]'::jsonb, null, 280, true, 'published', 3),
  ('Brewly Coffee Rebrand', 'brewly-coffee-rebrand', 'Branding', 2025, 'Brewly', 'Brand Identity', 'A warm, friendly identity and packaging system for a growing chain of coffee shops.', 'The business was getting traffic but very few enquiries. The old website was slow on mobile, hard to update and did not explain clearly why customers should choose them.', 'We started with a short discovery workshop, rewrote the key messages, and designed a fast, mobile-first website with clear calls to action. A simple dashboard lets the team update content without a developer.', 'Page speed improved to 95+, and enquiries more than doubled in the first three months. The team now publishes new offers and articles every week on their own.', '/demo/project-brewly.svg', '["/demo/project-brewly.svg","/demo/project-aurora.svg"]'::jsonb, null, 350, true, 'published', 4),
  ('MediCare Clinic Growth', 'medicare-clinic-growth', 'Marketing', 2024, 'MediCare Clinic', 'SEO & Google Ads', 'Local SEO and ad campaigns that filled a dental clinic''s calendar within 90 days.', 'The business was getting traffic but very few enquiries. The old website was slow on mobile, hard to update and did not explain clearly why customers should choose them.', 'We started with a short discovery workshop, rewrote the key messages, and designed a fast, mobile-first website with clear calls to action. A simple dashboard lets the team update content without a developer.', 'Page speed improved to 95+, and enquiries more than doubled in the first three months. The team now publishes new offers and articles every week on their own.', '/demo/project-medicare.svg', '["/demo/project-medicare.svg","/demo/project-propnest.svg"]'::jsonb, 'https://example.com', 190, false, 'published', 5),
  ('PropNest Real Estate', 'propnest-real-estate', 'Websites', 2024, 'PropNest', 'Design & Development', 'A property listing website with smart search filters and lead capture forms.', 'The business was getting traffic but very few enquiries. The old website was slow on mobile, hard to update and did not explain clearly why customers should choose them.', 'We started with a short discovery workshop, rewrote the key messages, and designed a fast, mobile-first website with clear calls to action. A simple dashboard lets the team update content without a developer.', 'Page speed improved to 95+, and enquiries more than doubled in the first three months. The team now publishes new offers and articles every week on their own.', '/demo/project-propnest.svg', '["/demo/project-propnest.svg","/demo/project-medicare.svg"]'::jsonb, null, 260, false, 'published', 6);
